  </div>
</main>

<script>
(function() {
  var form = document.getElementById('regForm');
  var successBanner = document.getElementById('successBanner');
  var alertSummary = document.getElementById('alertSummary');
  var passwordToggle = document.getElementById('passwordToggle');
  var passwordInput = document.getElementById('password');
  var confirmPasswordInput = document.getElementById('confirmPassword');

  // Toggle password visibility for both inputs
  passwordToggle.addEventListener('click', function() {
    var isHidden = passwordInput.type === 'password';
    if (isHidden) {
      passwordInput.type = 'text';
      confirmPasswordInput.type = 'text';
      this.textContent = 'Hide';
      this.setAttribute('aria-label', 'Hide password');
    } else {
      passwordInput.type = 'password';
      confirmPasswordInput.type = 'password';
      this.textContent = 'Show';
      this.setAttribute('aria-label', 'Show password');
    }
  });

  function showError(fieldId, msg) {
    var errEl = document.getElementById(fieldId + 'Err');
    var input = document.getElementById(fieldId);
    if (errEl) errEl.textContent = msg;
    if (input) input.setAttribute('aria-invalid', 'true');
  }

  function clearError(fieldId) {
    var errEl = document.getElementById(fieldId + 'Err');
    var input = document.getElementById(fieldId);
    if (errEl) errEl.textContent = '';
    if (input) input.removeAttribute('aria-invalid');
  }

  function clearAllErrors() {
    ['username','email','dob','password','confirmPassword','terms'].forEach(clearError);
  }

  function validateUsername(value) {
    var trimmed = value.trim();
    if (!trimmed) return 'Username is a required field.';
    if (trimmed.length < 3) return 'Username must be at least 3 characters.';
    if (trimmed.length > 20) return 'Username must be 20 characters or fewer.';
    if (!/^[a-zA-Z]/.test(trimmed)) return 'Username must start with a letter.';
    if (!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(trimmed)) return 'Username may only contain letters, digits, and underscores.';
    return null;
  }

  function validateEmail(value) {
    var trimmed = value.trim();
    if (!trimmed) return 'Email address is a required field.';
    // Must have exactly one @
    var atIdx = trimmed.indexOf('@');
    if (atIdx <= 0) return 'Please enter a valid email address.';
    if (trimmed.indexOf('@', atIdx + 1) !== -1) return 'Please enter a valid email address.';
    var local = trimmed.substring(0, atIdx);
    var domain = trimmed.substring(atIdx + 1);
    // Local part checks
    if (!local) return 'Please enter a valid email address.';
    if (/\s/.test(local)) return 'Please enter a valid email address.';
    if (local.startsWith('.') || local.endsWith('.')) return 'Please enter a valid email address.';
    // Domain checks
    if (!domain) return 'Please enter a valid email address.';
    if (/\s/.test(domain)) return 'Please enter a valid email address.';
    // Split domain into labels
    var labels = domain.split('.');
    if (labels.length < 2) return 'Please enter a valid email address.';
    for (var i = 0; i < labels.length; i++) {
      var label = labels[i];
      if (!label) return 'Please enter a valid email address.';
      if (label.startsWith('-') || label.endsWith('-')) return 'Please enter a valid email address.';
    }
    return null;
  }

  function validateDob(value) {
    if (!value) return null;
    // Must match YYYY-MM-DD format
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return 'Please enter a valid date in YYYY-MM-DD format.';
    var parts = value.split('-');
    var year = parseInt(parts[0], 10);
    var month = parseInt(parts[1], 10);
    var day = parseInt(parts[2], 10);
    if (month < 1 || month > 12) return 'Please enter a valid date.';
    if (day < 1) return 'Please enter a valid date.';
    // Check days in month
    var daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    // Leap year check
    if ((year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0)) {
      daysInMonth[1] = 29;
    }
    if (day > daysInMonth[month - 1]) return 'Please enter a valid date.';
    return null;
  }

  function validatePassword(value) {
    if (!value) return 'Password is a required field.';
    if (value.length < 10) return 'Password must be at least 10 characters.';
    if (value.length > 64) return 'Password must be 64 characters or fewer.';
    if (!/[a-zA-Z]/.test(value)) return 'Password must contain at least one letter.';
    if (!/[0-9]/.test(value)) return 'Password must contain at least one digit.';
    return null;
  }

  function validateConfirmPassword(confirmValue, passwordValue) {
    if (!confirmValue) return 'Please confirm your password.';
    if (confirmValue !== passwordValue) return 'Passwords do not match.';
    return null;
  }

  function validateTerms() {
    var cb = document.getElementById('terms');
    if (!cb.checked) return 'You must accept the Terms of Service.';
    return null;
  }

  // Real-time validation on blur
  ['username','email','dob','password','confirmPassword'].forEach(function(id) {
    var el = document.getElementById(id);
    el.addEventListener('blur', function() {
      var err;
      if (id === 'confirmPassword') {
        err = validateConfirmPassword(el.value, passwordInput.value);
      } else if (id === 'username') {
        err = validateUsername(el.value);
      } else if (id === 'email') {
        err = validateEmail(el.value);
      } else if (id === 'dob') {
        err = validateDob(el.value);
      } else if (id === 'password') {
        err = validatePassword(el.value);
      }
      if (err) showError(id, err);
      else clearError(id);
    });
    el.addEventListener('input', function() {
      if (el.getAttribute('aria-invalid') === 'true') {
        var err;
        if (id === 'confirmPassword') {
          err = validateConfirmPassword(el.value, passwordInput.value);
        } else if (id === 'username') {
          err = validateUsername(el.value);
        } else if (id === 'email') {
          err = validateEmail(el.value);
        } else if (id === 'dob') {
          err = validateDob(el.value);
        } else if (id === 'password') {
          err = validatePassword(el.value);
        }
        if (!err) clearError(id);
      }
    });
  });

  document.getElementById('terms').addEventListener('change', function() {
    var err = validateTerms();
    if (err) showError('terms', err);
    else clearError('terms');
  });

  // Storage functions using localStorage
  function getRegisteredUsers() {
    try {
      var data = localStorage.getItem('_registered_users');
      return data ? JSON.parse(data) : [];
    } catch(e) {
      return [];
    }
  }

  function saveRegisteredUser(username, email, dob) {
    var users = getRegisteredUsers();
    var record = { username: username.toLowerCase(), email: email.toLowerCase() };
    if (dob) record.dob = dob;
    users.push(record);
    localStorage.setItem('_registered_users', JSON.stringify(users));
  }

  function isDuplicateUsername(username) {
    var users = getRegisteredUsers();
    var u = username.toLowerCase();
    return users.some(function(user) {
      return user.username === u;
    });
  }

  function isDuplicateEmail(email) {
    var users = getRegisteredUsers();
    var e = email.toLowerCase();
    return users.some(function(user) {
      return user.email === e;
    });
  }

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    successBanner.style.display = 'none';
    successBanner.textContent = '';
    alertSummary.style.display = 'none';
    alertSummary.textContent = '';

    clearAllErrors();

    var usernameVal = document.getElementById('username').value;
    var emailVal = document.getElementById('email').value;
    var dobVal = document.getElementById('dob').value;
    var passwordVal = document.getElementById('password').value;
    var confirmVal = document.getElementById('confirmPassword').value;

    var errors = [];
    var firstErrorField = null;

    // Validate username
    var usernameErr = validateUsername(usernameVal);
    if (usernameErr) {
      errors.push(usernameErr);
      showError('username', usernameErr);
      if (!firstErrorField) firstErrorField = document.getElementById('username');
    }

    // Validate email
    var emailErr = validateEmail(emailVal);
    if (emailErr) {
      errors.push(emailErr);
      showError('email', emailErr);
      if (!firstErrorField) firstErrorField = document.getElementById('email');
    }

    // Validate DOB
    var dobErr = validateDob(dobVal);
    if (dobErr) {
      errors.push(dobErr);
      showError('dob', dobErr);
      if (!firstErrorField) firstErrorField = document.getElementById('dob');
    }

    // Validate password
    var passwordErr = validatePassword(passwordVal);
    if (passwordErr) {
      errors.push(passwordErr);
      showError('password', passwordErr);
      if (!firstErrorField) firstErrorField = document.getElementById('password');
    }

    // Validate confirm password
    var confirmErr = validateConfirmPassword(confirmVal, passwordVal);
    if (confirmErr) {
      errors.push(confirmErr);
      showError('confirmPassword', confirmErr);
      if (!firstErrorField) firstErrorField = document.getElementById('confirmPassword');
    }

    // Validate terms
    var termsErr = validateTerms();
    if (termsErr) {
      errors.push(termsErr);
      showError('terms', termsErr);
      if (!firstErrorField) firstErrorField = document.getElementById('terms');
    }

    if (errors.length > 0) {
      alertSummary.textContent = 'There are errors in your registration. Please correct the invalid input below.';
      alertSummary.style.display = 'block';
      if (firstErrorField) firstErrorField.focus();
      return;
    }

    // Normalize values
    var normalizedUsername = usernameVal.trim();
    var normalizedEmail = emailVal.trim().toLowerCase();

    // Check duplicates
    var dupErrors = [];
    if (isDuplicateUsername(normalizedUsername)) {
      dupErrors.push('An account with this username already exists.');
      showError('username', 'An account with this username already exists.');
      if (!firstErrorField) firstErrorField = document.getElementById('username');
    }
    if (isDuplicateEmail(normalizedEmail)) {
      dupErrors.push('An account with this email address already exists.');
      showError('email', 'An account with this email address already exists.');
      if (!firstErrorField) firstErrorField = document.getElementById('email');
    }

    if (dupErrors.length > 0) {
      alertSummary.textContent = 'There is a problem: an account with these details already exists. Please use different credentials.';
      alertSummary.style.display = 'block';
      if (firstErrorField) firstErrorField.focus();
      return;
    }

    // Save registration (no passwords stored)
    var dobToStore = dobVal || null;
    saveRegisteredUser(normalizedUsername, normalizedEmail, dobToStore);

    successBanner.textContent = 'Registration successful! Welcome, ' + normalizedUsername + '.';
    successBanner.style.display = 'block';
    form.reset();
    clearAllErrors();
    successBanner.focus();
  });
})();
</script>

</body>
</html>


