          <label for="email">Email Address <span aria-hidden="true">*</span></label>
          <input type="text" id="email" name="email" required autocomplete="email" aria-required="true" aria-describedby="emailErr">
          <div id="emailErr" class="error-msg" aria-live="polite"></div>
        </div>

        <div class="field">
          <label for="dob">Date of Birth</label>
          <input type="date" id="dob" name="dob" autocomplete="bday" aria-describedby="dobErr">
          <div id="dobErr" class="error-msg" aria-live="polite"></div>
